# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_lev_a import L,A
LV=[['拉丁 levis → levitas','轻 → 轻盈、轻率']]
LN=L+[['拉丁 levamen','减轻；在通俗拉丁用法中指使面团膨起的东西'],['古法语 levain → 英语 leaven','发酵、膨松用的材料；使膨起']]
LC=[['拉丁 levis','轻'],['重建的通俗拉丁 *leviarius → 法语 léger','轻的、轻快的']]
WC=[
E('levity','/ˈlevɪti/','轻率、不庄重；轻松诙谐','本来该认真承受的分量，被人处理得太轻了；也可以只是沉重气氛里的一点轻松。','经法语 levité 接拉丁 levitas，来自 levis“轻”；不要拆成现代英语 levy。',LV+[['法语 levité → 英语 levity','轻盈、轻率 → 不庄重；轻松诙谐']],'treat a serious matter with levity 常带批评：把严肃事情当儿戏。a moment of levity 也可以是紧张时刻的一点幽默，未必贬义。判断语气要看那份“轻”是否合时宜。','a moment of levity；inappropriate levity；treat with levity。','humour 是幽默；levity 更突出态度或气氛的轻松，有时暗示轻松过头。',('A brief moment of levity eased the tension in the room.','片刻的轻松诙谐缓和了房间里的紧张气氛。'),('She objected to the levity with which they discussed the serious mistake.','她反对他们用如此轻率的态度讨论那个严重错误。'),sources=['https://www.etymonline.com/word/levity']),
E('levitate','/ˈlevɪteɪt/','悬浮；使悬浮','物体离开地面，在空中停住，看上去像摆脱了向下的重量。','接拉丁 levis／levitas“轻、轻盈”，近代构词与 gravitate 相对；不可硬拆成现代 levy + tate。',LV+[['近代拉丁、英语中的 levitate 一类构词','与重力下落相对的升起、悬浮表达'],['英语 levitate','悬在空中；使物体悬浮']],'磁力可以使物体 levitate；魔术表演也可能营造悬浮效果。看到这个词本身，不能就认定发生了超自然现象；需要看文本说的是装置、表演还是声称的能力。','levitate above；make something levitate。','float 可表示浮在水面、空气中等；levitate 常突出离开支撑面而悬在空中。',('The small magnet appeared to levitate above the base.','那块小磁体看起来悬浮在底座上方。'),('The magician made a paper ring seem to levitate.','魔术师让一个纸环看起来悬浮了起来。'),sources=['https://www.etymonline.com/word/levitate']),
E('levitation','/ˌlevɪˈteɪʃən/','悬浮；悬浮现象或效果','把“离开支撑、悬在空中”这个现象作为一个名词来说。','与 levitate 共同接拉丁 levis／levitas 的“轻”意；现代可认作对应 -ation 名词，但英语名词记录早于动词记录，不能写成动词先诞生再派生名词。',LV+[['十七世纪 levitation／levitate 一组新造词','表达升起、悬浮；名词与动词的记录并不同步'],['英语 levitation','悬浮这一现象、过程或效果']],'magnetic levitation 是磁悬浮；a levitation trick 是营造悬浮效果的魔术。名词只给现象命名，不说明所有悬浮依靠同一种机制。','magnetic levitation；a levitation demonstration；a levitation effect。','levity 是轻率或轻松；levitation 是悬浮。两词都连到“轻”，现代意思却不能互换。',('The demonstration explained the principle of magnetic levitation.','演示说明了磁悬浮的原理。'),('The stage lighting helped create the illusion of levitation.','舞台灯光帮助营造了悬浮的错觉。'),sources=['https://www.etymonline.com/word/levitation','https://www.etymonline.com/word/levitate']),
E('maglev','/ˈmæɡlev/','磁悬浮；磁悬浮列车','把 magnetic levitation 两个词缩成一个词：用磁力让车辆悬起。','magnetic 的 mag- + levitation 的 lev-，属于截取两词片段形成的混成词。',LV+[['英语 levitation + magnetic','悬浮 + 磁的'],['magnetic levitation → maglev','磁悬浮；采用磁悬浮的交通系统或列车']],'a maglev train 是磁悬浮列车。lev 在这里不是一个新拉丁词，而是现代英语 levitation 的缩片；各种磁悬浮方案的具体技术不完全一样。','a maglev train；maglev technology；a maglev system。','maglev 是悬浮方式相关的称呼；high-speed train 按速度和系统特征分类，不能把所有高速列车都叫 maglev。',('The exhibition includes a model of a maglev train.','展览里有一辆磁悬浮列车模型。'),('Students compared maglev technology with conventional rail systems.','学生比较了磁悬浮技术与传统铁路系统。'),sources=['https://www.energy.gov/articles/how-maglev-works']),
E('leaven','/ˈlevən/','发酵剂、膨松剂；使发起；使气氛或内容活跃','一点材料让整团面慢慢鼓起来，也可比喻一点因素改变整件事的味道。','古法语 levain 接拉丁 levamen；背后是 levare“抬起、使轻”。',LN,'leaven dough 是使面团发起、变松。leaven a speech with humour 是给讲话加一点幽默，让它不那么沉闷。比喻里改变整体的因素不一定总是好东西，要看具体语境。','leaven dough；leaven something with humour；a leaven of。','yeast 是酵母；leaven 范围更宽，可泛说使面团膨起的材料或作用，并不限于酵母。',('The baker used a small amount of starter to leaven the dough.','面包师用了少量酵种让面团发起。'),('She leavened the serious lecture with a few gentle jokes.','她在严肃的讲座中穿插了几个温和的笑话，让气氛轻松一些。'),sources=['https://www.etymonline.com/word/leaven']),
E('leavening','/ˈlevənɪŋ/','膨松剂；使面团发起的过程；活跃气氛的因素','让一整团东西从紧实变蓬松的材料或作用。','leaven + -ing，既可指过程，也可指起膨松作用的材料。',A(LN,'英语 leavening','使发起的过程；使发起的材料；改变整体气氛的成分'),'a leavening agent 可是酵母、泡打粉等；the leavening of dough 是面团膨起的过程。a leavening of humour 是掺入一点幽默，给原本沉闷的内容松松劲。','a leavening agent；chemical leavening；a leavening of humour。','fermentation 是发酵过程；leavening 按使面团膨松的作用来命名，化学膨松也可属于 leavening。',('The recipe uses baking powder as its leavening agent.','这份配方用泡打粉作膨松剂。'),('A leavening of humour kept the long talk engaging.','穿插其中的幽默让长篇讲话仍然吸引人。')),
E('unleavened','/ʌnˈlevənd/','未发酵膨起的；不加膨松剂的〔面饼等〕','面团没有靠膨松过程鼓起来，做出的面饼常较薄、较紧实。','un-“不” + leavened“经膨松的”；leaven + -ed 构成后者。',A(LN,'英语 leavened → unleavened','发起的 → 未发起的'),'unleavened bread 通常指不靠发酵剂或膨松剂发起的饼。它照样可以经过烘烤或其他加热；不能因 un- 就理解成没熟，也不能据此判断是否含小麦或麸质。','unleavened bread；an unleavened flatbread。','unleavened 说膨松方式；uncooked 说有没有烹熟，两件事不同。',('The meal included a thin unleavened bread.','这顿饭里有一种薄薄的无酵饼。'),('She rolled the unleavened dough into small circles before cooking it.','她把未发起的面团擀成小圆片，再下锅烹制。')),
E('levator','英 /lɪˈveɪtə/；美 /lɪˈveɪtər/','提肌〔把某部位提起的肌肉〕','身体里负责把某个部位往上拉的“小吊机”。','解剖学新拉丁 levator，来自拉丁 levare“抬起”，-tor 表执行者。',L+[['新拉丁解剖名 levator','承担抬举功能的肌肉'],['英语 levator','某部位的提肌；常与部位名称合用']],'levator 是按功能给肌肉起的名字：它把相应部位提起来。完整肌名通常还会交代提的是哪里，例如眼睑；单独一个 levator 不总能确定是哪块肌肉。','a levator muscle；the levator of the eyelid。','elevator 日常首先想到电梯；levator 是解剖名称。完整肌名通常还指出它作用的部位。',('The diagram labels the levator muscle of the eyelid.','图上标出了眼睑的提肌。'),('The students compared the actions of the levator and the depressor.','学生比较了提肌和降肌的作用。'),sources=['https://www.merriam-webster.com/dictionary/levator']),
E('superelevation','/ˌsuːpərˌeləˈveɪʃən/','超高；弯道外侧抬高、倾斜设置〔工程〕','弯道不是平躺的，常把外侧抬高一点，让路面或轨道向弯内倾。','super-“在上、更高” + elevation“抬高、高度”。',L+[['拉丁 elevatio → 英语 elevation','抬高；高度'],['英语 super- + elevation → superelevation','额外抬高；工程中弯道横向倾斜设置']],'道路和铁路语境里，superelevation 常说弯道的横向倾斜或对应高度差。核心不是整条路都更高，而是弯道两侧有意设置不同高度；这样能让倾斜产生的作用帮助车辆转弯。','superelevation on a curve；the superelevation rate。','elevation 常说一个地点相对基准的高度；superelevation 在弯道设计里关注横向坡度或两侧高差。',('The drawing shows the superelevation through the curve.','图纸展示了弯道段的超高设置。'),('The engineers checked the superelevation before approving the track design.','工程师在批准轨道设计前检查了超高设置。'),sources=['https://highways.fhwa.dot.gov/safety/speed-management/speed-concepts-informational-guide/chapter-4-engineering-and-technical']),
E('legerity','/ləˈdʒerəti/','轻快；敏捷〔罕见、书面〕','动作或思路像没有拖累的重量，轻轻一转就跟上了。','法语 légèreté“轻、敏捷”，来自 léger“轻”；后者经重建的 *leviarius 接拉丁 levis。',LC+[['法语 légèreté → 英语 legerity','轻盈、敏捷']],'可以说身体动作轻捷，也可以说思考敏锐灵活。这个词现在很少见，阅读旧文或刻意文雅的描写时认识即可，日常通常用 agility 或 nimbleness。','mental legerity；the legerity of a dancer。','levity 常说态度轻率或气氛轻松；legerity 更突出轻捷、灵活，不必带不庄重的意思。',('The essay praises the dancer’s legerity and control.','文章赞扬了舞者的轻捷与控制力。'),('He answered the unexpected question with remarkable legerity.','他思路灵活，迅速答上了那个意外的问题。'),sources=['https://www.merriam-webster.com/dictionary/legerity']),
E('legerdemain','英 /ˌledʒədəˈmeɪn/；美 /ˌledʒərdəˈmeɪn/','戏法手法；巧妙手腕；障眼法','手快得像没有重量，观众还没看清，东西已经变了位置。','法语 léger de main“手轻快”：léger“轻” + de“……的” + main“手”；main 接拉丁 manus，是另一个词根。',LC+[['法语 léger de main','手轻快、手巧'],['英语 legerdemain','手上戏法 → 巧妙手腕、掩饰真实情况的花招']],'舞台上可以指灵巧的手上戏法；verbal legerdemain 可以说用话术把问题绕开。比喻用法有时赞手腕巧妙，有时批评用技巧遮掩实情，要看语气。','a feat of legerdemain；verbal legerdemain；financial legerdemain。','magic 可泛指魔术或魔法；legerdemain 突出技巧、手法。这里的 main 是法语“手”，不是英语“主要的”。',('The audience admired the performer’s legerdemain.','观众赞叹表演者灵巧的戏法手法。'),('The critic called the explanation a piece of verbal legerdemain.','评论者称那番解释是一套文字障眼法。'),sources=['https://www.etymonline.com/word/legerdemain','https://www.merriam-webster.com/dictionary/legerdemain']),
E('Levant','英 /ləˈvænt/；美 /ləˈvɑːnt/','黎凡特，地中海东部一带的历史地理名称','从西欧望向太阳升起的方向，给东方地中海一带起了一个“升起之地”的名字。','法语 levant 是 lever“升起”的现在分词；lever 接拉丁 levare。',L+[['法语 lever → levant','升起 → 升起的，借指日出的方向'],['英语 Levant','东部地中海一带的历史地理名称']],'the Levant 常见于历史、考古、贸易和地区文化文字。这个名称指涉范围随时期和作者而变化，不是一条永远固定的现代国界线；重点先记“地中海东边”的方位画面。','the Levant；trade with the Levant；ports of the Levant。','Levant 是特定历史地理名称；east 是一般方向。这个名称来自观察位置，不能把它当成世界统一的东方起点。',('The book traces trade between Italy and the Levant.','这本书追溯了意大利与黎凡特之间的贸易。'),('The museum displays pottery from several parts of the Levant.','博物馆展出了来自黎凡特多个地区的陶器。'),sources=['https://www.etymonline.com/word/Levant']),
E('sublevation','构词参考 /ˌsʌblɪˈveɪʃən/','抬起；减轻、救助；起事〔古旧〕','从下面托一把，既能把东西抬高，也能让人不必独自承担全部重量。','拉丁 sub-“从下、在下” + levare → sublevare，经名词 sublevatio 接英语 sublevation。',L+[['拉丁 sublevare → sublevatio','从下面托起 → 抬起、减轻负担'],['英语 sublevation 的古旧用法','举升、救助；也可指起事、反抗']],'这是阅读旧文时可能遇到的词。它有“抬起、援助”的历史意义，也有“起事”的支线；不能因为看到 sub- 就自动翻成“压下去”。现代普通表达用 lifting、relief 或 uprising 更直接。','旧文中的 sublevation；the sublevation of a load。','sublevation 的 sub- 配合 levare 可以表示从下托起；它不是现代 subversion“颠覆”的常用替换词。',('The old manual uses “sublevation” for the lifting of a heavy load.','那本旧手册用 sublevation 表示抬起重物。'),('In this passage, “sublevation” refers to relief from a burden.','在这段文字里，sublevation 指减轻负担。'),sources=['https://en.wiktionary.org/wiki/sublevation']),
]
